/* FP:lib.rs-0130 */ crate :: rustc_index :: newtype_index ! { # [doc = " \"Universes\" are used during type- and trait-checking in the"] # [doc = " presence of `for<..>` binders to control what sets of names are"] # [doc = " visible. Universes are arranged into a tree: the root universe"] # [doc = " contains names that are always visible. Each child then adds a new"] # [doc = " set of names that are visible, in addition to those of its parent."] # [doc = " We say that the child universe \"extends\" the parent universe with"] # [doc = " new names."] # [doc = ""] # [doc = " To make this more concrete, consider this program:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " struct Foo { }"] # [doc = " fn bar<T>(x: T) {"] # [doc = "   let y: for<'a> fn(&'a u8, Foo) = ...;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " The struct name `Foo` is in the root universe U0. But the type"] # [doc = " parameter `T`, introduced on `bar`, is in an extended universe U1"] # [doc = " -- i.e., within `bar`, we can name both `T` and `Foo`, but outside"] # [doc = " of `bar`, we cannot name `T`. Then, within the type of `y`, the"] # [doc = " region `'a` is in a universe U2 that extends U1, because we can"] # [doc = " name it inside the fn type but not outside."] # [doc = ""] # [doc = " Universes are used to do type- and trait-checking around these"] # [doc = " \"forall\" binders (also called **universal quantification**). The"] # [doc = " idea is that when, in the body of `bar`, we refer to `T` as a"] # [doc = " type, we aren't referring to any type in particular, but rather a"] # [doc = " kind of \"fresh\" type that is distinct from all other types we have"] # [doc = " actually declared. This is called a **placeholder** type, and we"] # [doc = " use universes to talk about this. In other words, a type name in"] # [doc = " universe 0 always corresponds to some \"ground\" type that the user"] # [doc = " declared, but a type name in a non-zero universe is a placeholder"] # [doc = " type -- an idealized representative of \"types in general\" that we"] # [doc = " use for checking generic functions."] # [cfg_attr (feature = "nightly" , derive (HashStable_NoContext))] # [encodable] # [orderable] # [debug_format = "U{}"] # [gate_rustc_only] pub struct UniverseIndex { } }
